-- 50 demo people, imported through the same rules as the sign-up + profile + test forms
-- Plausible monthly rents for listings that had none ("rent on request"), by city and room type, rounded to 500.
UPDATE listings l SET rent = (round((b.lo + (b.hi - b.lo) * ((hashtext(l.id::text || l.title) & 1023) / 1023.0)) * CASE WHEN l.room_type = 'shared' THEN 0.75 ELSE 1 END / 500) * 500)::int
FROM (VALUES ('Mumbai',14000,24000),('Bengaluru',9000,17000),('Delhi',9000,16000),('Gurugram',10000,18000),('Noida',8000,14000),
             ('Ghaziabad',7000,12000),('Pune',7500,13000),('Chennai',8000,14000),('Hyderabad',8000,14000),('Kolkata',6500,11000),
             ('Ahmedabad',6500,11000),('Jaipur',6000,10000),('Chandigarh',8000,13000),('Bhopal',5000,8500),('Indore',5000,9000),
             ('Allahabad',4500,8000),('Prayagraj',4500,8000)) AS b(city, lo, hi)
WHERE lower(l.city) = lower(b.city) AND (l.rent IS NULL OR l.rent = 0);
UPDATE listings SET rent = 6000 + (hashtext(id::text) & 7) * 500 WHERE rent IS NULL OR rent = 0;
